CREATE TABLE IF NOT EXISTS Etudiant (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nom VARCHAR(100) NOT NULL, email VARCHAR(120) NOT NULL UNIQUE, mot_de_passe VARCHAR(60) NOT NULL, role VARCHAR(20) NOT NULL CHECK (role IN ('ETUDIANT','GESTIONNAIRE')));
CREATE TABLE IF NOT EXISTS Atelier (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, titre VARCHAR(180) NOT NULL, description VARCHAR(4000) NOT NULL, date_heure TIMESTAMP NOT NULL, capacite INTEGER NOT NULL CHECK (capacite > 0));
CREATE TABLE IF NOT EXISTS Inscription (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, etudiant_id BIGINT NOT NULL REFERENCES Etudiant(id), atelier_id BIGINT NOT NULL REFERENCES Atelier(id) ON DELETE RESTRICT, date_inscription TIMESTAMP NOT NULL, statut VARCHAR(20) NOT NULL CHECK (statut IN ('CONFIRMEE','ANNULEE')), CONSTRAINT uq_etudiant_atelier UNIQUE(etudiant_id,atelier_id));
CREATE INDEX IF NOT EXISTS ix_inscription_atelier_statut ON Inscription(atelier_id,statut);
